import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterOutlet, RouterModule, Router } from '@angular/router';
import { Subscription } from 'rxjs';
import { AuthService, User } from './services/auth.service';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule, RouterOutlet, RouterModule],
  templateUrl: './app.html',
  styleUrls: ['./app.css']
})
export class App implements OnInit, OnDestroy {
  title = 'Travlr Getaways Admin';
  currentUser: User | null = null;
  isAuthenticated = false;
  private subscriptions: Subscription[] = [];

  constructor(
    private authService: AuthService,
    private router: Router
  ) {}

  ngOnInit(): void {
    // Subscribe to authentication state
    this.subscriptions.push(
      this.authService.isAuthenticated$.subscribe(isAuth => {
        this.isAuthenticated = isAuth;
      })
    );

    // Subscribe to current user
    this.subscriptions.push(
      this.authService.currentUser$.subscribe(user => {
        this.currentUser = user;
      })
    );
  }

  ngOnDestroy(): void {
    this.subscriptions.forEach(sub => sub.unsubscribe());
  }

  logout(): void {
    this.authService.logout().subscribe({
      next: () => {
        this.router.navigate(['/login']);
      },
      error: (error) => {
        console.error('Logout error:', error);
        // Force logout even if server request fails
        this.authService.forceLogout();
        this.router.navigate(['/login']);
      }
    });
  }

  navigateToTrips(): void {
    this.router.navigate(['/trips']);
  }

  navigateToAddTrip(): void {
    this.router.navigate(['/add-trip']);
  }
}

<!-- Navigation Bar (only shown when authenticated) -->
<nav *ngIf="isAuthenticated" class="navbar navbar-expand-lg navbar-dark bg-primary shadow-sm">
  <div class="container">
    <!-- Brand -->
    <a class="navbar-brand fw-bold" routerLink="/trips">
      <i class="fas fa-plane me-2"></i>Travlr Admin
    </a>

    <!-- Mobile Toggle -->
    <button class="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#navbarNav">
      <span class="navbar-toggler-icon"></span>
    </button>

    <!-- Navigation Links -->
    <div class="collapse navbar-collapse" id="navbarNav">
      <ul class="navbar-nav me-auto">
        <li class="nav-item">
          <a class="nav-link" routerLink="/trips" routerLinkActive="active">
            <i class="fas fa-list me-1"></i>All Trips
          </a>
        </li>
        <li class="nav-item">
          <a class="nav-link" routerLink="/add-trip" routerLinkActive="active">
            <i class="fas fa-plus me-1"></i>Add Trip
          </a>
        </li>
      </ul>

      <!-- User Menu -->
      <div class="navbar-nav">
        <div class="nav-item dropdown">
          <a class="nav-link dropdown-toggle" href="#" role="button" data-bs-toggle="dropdown">
            <i class="fas fa-user-circle me-1"></i>{{ currentUser?.username || 'Admin' }}
          </a>
          <ul class="dropdown-menu dropdown-menu-end">
            <li>
              <a class="dropdown-item" href="#" (click)="logout()">
                <i class="fas fa-sign-out-alt me-2"></i>Logout
              </a>
            </li>
          </ul>
        </div>
      </div>
    </div>
  </div>
</nav>

<!-- Main Content -->
<main class="main-content" [class.with-navbar]="isAuthenticated">
  <router-outlet></router-outlet>
</main>

<!-- Footer (only shown when authenticated) -->
<footer *ngIf="isAuthenticated" class="footer bg-light border-top mt-auto">
  <div class="container py-3">
    <div class="row align-items-center">
      <div class="col-md-6">
        <p class="mb-0 text-muted">
          <i class="fas fa-copyright me-1"></i>
          {{ currentYear }} Travlr Getaways. All rights reserved.
        </p>
      </div>
      <div class="col-md-6 text-md-end">
        <small class="text-muted">
          <i class="fas fa-shield-alt me-1"></i>
          Secure Admin Panel
        </small>
      </div>
    </div>
  </div>
</footer>
